
'use strict';
const statusText={current:'Implemented',partial:'Restricted / mixed',target:'Target / not built'};
// Diagram coordinates are schematic. Component details are the authoritative textual equivalent.
const n=(id,title,sub,status,x,y,description,inputs,outputs,controls,failure,source)=>({id,title,sub,status,x,y,description,inputs,outputs,controls,failure,source});
const g=(title,x,y,w,h)=>({title,x,y,w,h});
const e=(from,to,label='',planned=false,route='')=>({from,to,label,planned,route});
const note=(title,text,status='')=>({title,text,status});
const views=[
{id:'system',label:'System map',title:'01 / The governed investigation system',description:'Six domains converge on the Relay control plane. Solid components describe the current pilot; dashed components describe the target.',height:1010,groups:[g('01 · Evidence domain',16,20,350,540),g('02 · Operator & control plane',395,20,350,540),g('03 · Agent execution',774,20,350,540),g('04 · State & knowledge',16,590,350,400),g('05 · Decision governance',395,590,350,400),g('06 · Operations & external systems',774,590,350,400)],nodes:[
n('corpus','Benchmark evidence','155,350 records · 16 observed hosts','current',32,85,'Defense Collective benchmark material is the current security evidence source. Seven event-ID-based review cohorts are open work queues, not confirmed attacks.','Imported benchmark event records.','Case-scoped records with source and original raw JSON.',['No local conversation history was imported into the pilot.','Preserve original evidence; findings remain separate.'],'Incomplete or misleading evidence must result in uncertainty, not a fabricated threat verdict.','services/import_corpus.py · store.py · FLY_PILOT.txt'),
n('ingest','Source acquisition','Explicit importer today; sensors later','partial',32,250,'The implemented path is an explicit, non-overwriting corpus importer. Continuous Wazuh, Sysmon/agent, cloud-audit or SIEM connectors remain target work.','Benchmark archive now; authenticated sensor batches proposed.','Normalized event rows now; proposed lineage, deduplication and dead-letter records.',['Treat log content as untrusted data, not instructions.','Target: enforce payload limits, source identity and retention.'],'Target connectors must quarantine malformed batches and retain replay checkpoints.','services/import_corpus.py · export_pilot.py'),
n('evidence','Evidence service','Bounded queries · case membership','current',32,415,'Only the selected case is queryable through model-facing tools. Raw records remain inspectable in the analyst UI.','Case ID, search filter, record ID.','Up to 25 records per query; bounded excerpts.',['Case membership is checked server-side.','Query excerpts: 1,800 characters; individual record: 6,000.'],'Cross-case event IDs fail; no broader corpus access is silently substituted.','services/store.py · engine.py'),
n('ui','Analyst workspace','Cases · chat · trace · approvals','current',411,85,'A browser-based, plain HTML/CSS/JavaScript application. Investigations, agent learning controls and runtime visibility share one interface.','Authenticated operator actions and prompts.','JSON requests and rendered NDJSON events.',['Provider keys never enter the browser.','Display source text as data.'],'Show run failures and pending approvals separately from final findings.','web/app.js · advanced.js · frameworks.js · catalog.js'),
n('api','Authenticated API','Cookie session · HTTP / NDJSON','current',411,250,'The Python standard-library HTTP server owns access checks and run admission. The Fly pilot serves the same app behind HTTPS.','JSON requests and secure operator cookie.','Session/control responses, evidence and persisted run events.',['Exact Host/Origin checks; JSON POSTs.','32 HTTP worker slots; pilot run concurrency is one.'],'Reject unauthenticated requests, wrong origins and busy sessions.','services/app.py · access.py'),
n('engine','Relay control plane','Session → context → runtime → audit','current',411,415,'The engine governs execution without replacing each framework’s native model loop. Runtime choice and feature switches are fixed in session configuration.','Prompt, immutable session configuration, evidence scope.','Tool receipts, lifecycle events, validated outcomes and checkpoints.',['180-second runtime deadline; cancellation.','Read-only, ask-all and supervised tool policy.'],'Persist failed/cancelled outcomes. Do not report a failed turn as success.','services/engine.py · adapters/common.py'),
n('registry','Runtime registry','Allowlist · enable switch · readiness','current',790,85,'Installation, configuration, feature support and live verification are distinct. Disabling a runtime is not equivalent to uninstalling its dependencies.','Runtime ID, package availability, server-side configuration.','Validated adapter selection or explicit unsupported-feature rejection.',['No arbitrary module loading.','Active adapters cannot be disabled mid-run.'],'Fail closed when dependencies, credentials or capabilities are missing.','services/adapters/registry.py'),
n('workers','Framework runtimes','Python native + private stdio workers','partial',790,250,'Eleven executable adapters plus deterministic replay. Framework-specific loops are retained behind the shared Relay gateway.','Selected runtime, context, permitted tool definitions.','Normalized trace, tool requests, native continuation and terminal result.',['Node and isolated Python dependency environments.','Subprocess separation is not an OS sandbox.'],'Terminate on deadline or cancellation; keep authorized side effects in the audit.','services/adapters/* · workers/*'),
n('new-sdk','Strands + Mastra','Two explicit extension slots','target',790,415,'Proposed adapters use the same governance contract. Strands adds orchestration experiments; Mastra adds TypeScript agent/workflow experiments. Neither is implemented in this baseline.','Registry manifest, provider policy, case-scoped tools.','Testable run, cancel, stream and continuation behavior.',['Disabled until adapter contract tests pass.','Native features must remain separately labeled.'],'Unsupported native controls fail visibly; no silent fallback to replay.','Design proposal · official references below'),
n('state','Evidence & operational state','SQLite WAL + native state files','current',32,655,'Evidence and Relay state currently share a SQLite database on the persistent volume. Native SDK files live beside it, except OpenCode’s dedicated server state.','Events, sessions, traces, approvals and SDK anchors.','Restart-persistent case data and successful continuation references.',['Raw audit is retained across compaction.','Backups must cover database and native files consistently.'],'No automatic crash-resume or distributed transactional execution.','services/store.py · adapters/state.py'),
n('memory','Memory & report layer','Case findings · tasks · report versions','partial',32,820,'Shared Relay memory is evidence-linked case knowledge, not universal SDK-native memory or a vector database. Reports are versioned separately from raw evidence.','Approved findings, task updates and artifact content.','Case-scoped recall, investigation plans, reversible report versions.',['Memory writes need approval and in-case evidence references.','Mem0/vector retrieval remains a future option.'],'Never allow memory content to grant permissions or override system policy.','services/advanced.py'),
n('policy','Tool policy gateway','Validate → authorize → execute → receipt','current',411,655,'All full-loop adapters must pass shared tools through engine policy; the model’s prompt is not the security boundary.','Tool name and structured arguments.','Denied, approval-pending or executed result.',['Allowlisted tools and feature gates.','Exact stored arguments are approved once.'],'A pending approval executes nothing. A process crash is not an exactly-once guarantee.','services/engine.py'),
n('decision','Analyst decision','Evidence-supported report; dry-run action','partial',411,820,'The application supports investigation artifacts and simulated containment. It does not isolate hosts, revoke credentials or execute production remediation.','Cited evidence, findings, uncertainty and analyst review.','Approved case notes and versioned report; simulation receipt.',['No endpoint/control connector exists.','Separate model proposal from analyst authority.'],'Missing evidence stays unknown; simulated action must never be labeled applied.','services/advanced.py · engine.py'),
n('observe','Audit & learning feedback','Trace · usage · JSON / OTLP export','partial',790,655,'Relay stores execution events and supports audit and OTLP JSON export. This is outgoing run observability, not incoming OpenTelemetry security sensors.','Lifecycle events, tool receipts and adapter-reported usage.','Reviewable trace, cost estimates where supplied and export artifacts.',['Remote provider tracing is disabled in configured integrations.','Contract tests are not provider-quality benchmarks.'],'Missing usage is unknown, not zero. Exports can contain sensitive evidence.','services/advanced.py · SDK_COVERAGE.md'),
n('cloud','Fly protected pilot','1 machine · Toronto · persistent volume','partial',790,820,'Recorded deployment: one shared CPU, 2 GB RAM, 1 GB encrypted volume, idle stop and HTTP start. Shared operator login; no provider keys provisioned.','Authenticated HTTPS traffic.','Single-machine laboratory service.',['No multi-tenant or replica scaling claim.','OpenCode disabled; Hermes not bundled.'],'Cold start invalidates in-memory login sessions. Off-machine restore drills remain outstanding.','FLY_PILOT.txt · fly.toml · Dockerfile')],edges:[e('corpus','ingest'),e('ingest','evidence'),e('ui','api'),e('api','engine'),e('registry','workers'),e('workers','new-sdk','extension',true),e('evidence','engine','evidence'),e('engine','workers','invoke',false,'up-right'),e('engine','policy'),e('policy','decision'),e('evidence','state'),e('state','memory'),e('workers','observe','events',false,'outer-right'),e('observe','cloud'),e('state','policy','reads / writes'),e('decision','cloud','UI result')],notes:[note('Control plane, not a mega-agent','Keep authorization, case scope, audit, and resource admission in Relay. Keep native model/tool-loop behavior inside each adapter.'),note('Model access is an external trust boundary','Selected evidence leaves the application during a real provider call. Authorize data handling and provision credentials server-side before live acceptance.'),note('An honest baseline','11 SDK adapters exist; 2 more are designed here. Replay is deterministic. No claim of every upstream capability, live threat detection or production readiness.')]},
{id:'loop',label:'Agent lifecycle',title:'02 / A prompt is a governed execution, not just a chat message',description:'Read left to right, then down. Tool results return to the native model loop; approval and cancellation remain outside model authority.',height:870,groups:[g('Admission & context',16,20,1108,220),g('Native loop & execution boundary',16,275,1108,255),g('Persistence & failure semantics',16,565,1108,275)],nodes:[
n('l1','1. Admit & persist','Authenticate · lock session · record prompt','current',32,95,'Accept a prompt only for an authenticated, admitted session; record the user message and run start before invoking the runtime.','Operator prompt and session ID.','Trace events message.user and run.started.',['Immutable config and case scope.','Global pilot concurrency gate and per-session busy check.'],'Busy requests are rejected, not run concurrently in the same session.','services/app.py · engine.py · store.py'),
n('l2','2. Assemble context','Summary + retained events + native anchor','current',411,95,'Relay builds bounded context and restores the selected adapter’s continuation. The character threshold is an application heuristic, not the actual model token window.','Session summary, retained trace and native state reference.','Runtime prompt/history and scoped tool schemas.',['Between-turn compaction keeps a verified checkpoint.','Native histories are isolated by runtime and compaction epoch.'],'Oversized native state is rejected above 4 MiB; compact before retrying.','services/engine.py · store.py · adapters/state.py'),
n('l3','3. Select native loop','SDK owns model turns and tool requests','partial',790,95,'The selected adapter calls its SDK with configured model and limits. Replay is a distinct no-model path. Model output may be tokens, lifecycle events or a terminal result.','Context, permitted tools, provider credentials.','Assistant events, proposed tool calls, final output.',['180-second outer deadline.','Turn/output bounds are adapter-specific; not universal USD caps.'],'A missing or invalid terminal result is a failed run, not a completed investigation.','services/adapters/* · claude_runtime.py'),
n('l4','4. Authorize tool call','Name · schema · feature · case · policy','current',790,355,'The gateway validates the call and enforces disabled tools and feature flags before dispatch. Read-only blocks writes and simulation; ask-all gates reads too.','SDK tool name and arguments.','Denied call, approval request or execution authorization.',['Never trust a model-generated claim of approval.','No arbitrary SQL, shell or network tool gateway.'],'Unknown tools and out-of-case evidence requests fail closed.','services/engine.py · adapters/common.py'),
n('l5','5. Human gate','Exact arguments · bounded live wait','current',411,355,'For gated tools, store the exact proposed call. Analyst approval consumes that pending request; the waiting SDK receives the stored receipt instead of rerunning it.','Pending approval ID and analyst approve/deny.','Execution receipt or denial/expiry event.',['Default approval/input wait: 90 seconds.','Pending requests execute no action.'],'Denied, expired or interrupted approvals do not proceed. Durable approval rows are not durable suspended workflow execution.','services/engine.py · relay_approvals'),
n('l6','6. Execute & return','Bounded result → native model loop','current',32,355,'Execute only the allowed operation, persist the result and return it to the SDK for the next turn. Native Claude file permissions have a separate SDK execution receipt path.','Authorized tool call or approved stored arguments.','hook.pre_tool, tool.started, tool.result, hook.post_tool.',['Raw evidence never mutated.','Approved local side effects may already exist if the run later fails.'],'Tool errors are recorded. Transcript rollback does not undo side effects.','services/engine.py · advanced.py · workspace.py'),
n('l7','7. Validate final result','Typed findings where supported','partial',32,660,'Validate supported structured findings and evidence references, then record final output and checkpoint. Hermes and OpenHands do not expose typed findings in this integration.','SDK terminal output and evidence references.','Assistant result and verified checkpoint.',['Do not fabricate a provider result from a failed stream.','Findings remain analyst-reviewed hypotheses.'],'Invalid structured output is failure; retain diagnostic trace.','services/adapters/common.py · SDK_COVERAGE.md'),
n('l8','8. Publish continuation','Successful anchor; raw audit retained','partial',411,660,'Ten non-Claude adapters publish a new continuation anchor only after validated success. Claude retains native SDK session behavior, including possible failed-turn partial history.','Validated result and runtime-native state.','Updated relay_native_state or native session reference.',['Branch creates a new Relay session from a summary.','Compaction resets native continuation, not audit.'],'No automatic replay of interrupted tools. On restart, reconcile before a new run.','services/adapters/state.py · store.py'),
n('l9','Stop / fail / recover','Cancel signal · deadline · explicit outcome','partial',790,660,'All terminal paths preserve trace and return the session to idle. Process restart recovery marks interrupted work; it does not safely resume arbitrary native execution.','Cancellation, timeout, SDK exception or restart.','run.failed / run.cancelled and recovery state.',['No silent provider fallback.','No guarantee of undo for completed side effects.'],'Target durable workers need leases, idempotency and reconciliation before restart-safe execution.','services/engine.py · store.py')],edges:[e('l1','l2'),e('l2','l3'),e('l3','l4'),e('l4','l5','if gated'),e('l5','l6','approved'),e('l3','l7','terminal result',false,'final-route'),e('l4','l6','read allowed',false,'read-route'),e('l7','l8'),e('l3','l9','exception / cancel',false,'outer-right'),e('l6','l3','tool result → next turn',false,'loop-top')],notes:[note('What consumes model context','System instructions, tool schemas, user prompts, selected evidence, prior messages and tool receipts. Native SDK context management varies; Relay’s character estimate is not an exact token meter.'),note('Approval is a state machine','pending → executing → executed, or denied / expired / failed. Native SDK permissions require the SDK to execute after approval. Crashes can leave effects without a final receipt; reconcile rather than retry blindly.'),note('Learning view','The execution trace should teach the difference between an SDK turn, a message, a tool proposal, an approved execution, a checkpoint and a reusable session. Those are not interchangeable units.')]},
{id:'runtime',label:'Runtime fabric',title:'03 / Plug-and-play without erasing SDK differences',description:'The common contract stays narrow. Native capabilities remain explicit extensions rather than pretending every framework behaves identically.',height:875,groups:[g('Shared control surface',16,20,1108,220),g('Execution lanes',16,275,1108,240),g('Governed extensions',16,550,1108,300)],nodes:[
n('r1','Adapter manifest','ID · version · features · enabled state','current',32,95,'A fixed runtime allowlist declares entrypoints and supported configuration. UI setup diagnostics separate package availability and credentials from live acceptance.','Selected runtime and session options.','Supported configuration or validation error.',['No dynamic code installation via the model.','No feature checkbox that bypasses backend validation.'],'Unsupported controls must fail visibly, not be ignored.','services/adapters/registry.py'),
n('r2','Shared run contract','Prompt / stream / tools / state / cancel','partial',411,95,'The current abstraction maps each runtime into Relay traces, tool dispatch and persisted continuation. Target: formal versioned protocol and compatibility negotiation.','Case context, budget, tool schemas, native reference.','Ordered events, tool requests, final result, usage and state.',['Do not claim all events are token streams.','Preserve framework-specific native metadata.'],'Target protocol adds schema versioning and deterministic rejection of unknown message types.','adapters/common.py · workers/*/runner.*'),
n('r3','Provider boundary','Server-side credentials; approved evidence','partial',790,95,'Adapters use their configured provider routes. The pilot has no paid provider credentials. External model access requires a separate data-handling and cost decision.','Filtered context and selected server-side key.','Model output, usage or provider error.',['Only selected worker credentials inherited.','No keys in browser, Git or container image.'],'Rate limits and model failures must surface explicitly. Target: egress allowlists and org spend reservation.','workers/python-bridge · SDK_COVERAGE.md'),
n('r4','Native Python lane','Claude · Pydantic · Deep · OpenAI','current',32,350,'Python adapters bind SDK-native loops directly. Claude also uses its SDK subprocess model and embedded Relay MCP tool server.','Shared engine and adapter-specific configuration.','SDK lifecycle, tool dispatch and native continuation.',['Claude and Deep Agents have restricted named specialists.','No general-purpose host tool exposure.'],'Library/process isolation differs by SDK; it is not hostile-code isolation.','services/claude_runtime.py · adapters/*'),
n('r5','Node worker lane','Pi · Vercel AI · OpenCode','partial',411,350,'Private NDJSON subprocess bridge for TypeScript/JavaScript SDKs. Pi/Vercel are full loop integrations; OpenCode is a snapshot connector to a dedicated loopback server.','Run envelope and explicit context.','Events, RPC tool calls and validated terminal result.',['Private stdio, not a public tool endpoint.','OpenCode server deny-all policy, no plugins/MCP.'],'Abort and parent deadline stop workers; remote OpenCode state needs separate lifecycle/backup.','workers/agent-bridge/runner.mjs'),
n('r6','Isolated Python lane','Google · Microsoft · OpenHands · Hermes','partial',790,350,'Private Python environments avoid conflicting dependencies and personal SDK profiles. Hermes has a separate pinned source/runtime and is not in the cloud image.','Minimal worker environment and run envelope.','Native events/history and Relay gateway calls.',['Only scoped custom toolsets; host tools disabled.','OpenHands emits lifecycle events, not token streaming.'],'Dependency isolation does not contain hostile execution; production needs OS-level worker boundaries.','workers/python-bridge/runner.py'),
n('r7','Strands integration slot','Start with bounded agents-as-tools','target',32,650,'Design choice: add a restricted Strands adapter, then explore graph, workflow and swarm patterns behind a shared budget. A2A remains a later separately authenticated boundary.','Relay tools, named read-only specialists and budget.','Normalized events plus native orchestration metadata.',['First pass: no autonomous write-capable swarm.','Every child inherits case scope, reduced tools and budget.'],'Acceptance requires loop, denial, cancellation, continuation and child-budget tests before activation.','Proposed · Strands official multi-agent guide'),
n('r8','Mastra integration slot','TypeScript agents + explicit workflows','target',411,650,'Design choice: extend the Node lane with Mastra. Keep SDK loop execution distinct from workflow execution, whose state needs configured durable storage.','Agent prompts or typed workflow inputs.','Workflow steps, suspension/resume state and findings.',['Relay approval is authority; native suspend is mechanism.','Workflow snapshots must be tied to Relay run and policy version.'],'Prove restart/resume and no duplicate side effects. Do not call an in-memory workflow durable.','Proposed · Mastra workflows and snapshots references'),
n('r9','Capability acceptance gate','Native ≠ shared ≠ disabled ≠ verified','target',790,650,'Make capability provenance a first-class adapter manifest: upstream supported, Relay integrated, disabled by policy, contract-tested and live-accepted are separate dimensions.','Pinned version, feature proof and acceptance artifacts.','Auditable capability matrix with evidence links.',['The current matrix already distinguishes native/shared/gaps.','Target: machine-readable proof per feature and release.'],'An untested feature is not green; a disabled dangerous feature is not necessarily missing engineering.','Design extension to services/inventory.py')],edges:[e('r1','r2'),e('r2','r3'),e('r1','r4'),e('r2','r5'),e('r3','r6'),e('r4','r7','new adapter',true),e('r5','r8','new adapter',true),e('r6','r9','acceptance',true)],notes:[note('One orchestrator owns a run','Use a single native orchestrator per experiment. Cross-framework delegation is a later explicit protocol, not uncontrolled nesting of independent loops and retry budgets.'),note('Shared governance stays shared','Evidence tools, approval, artifact versions, memory references and audit remain owned by Relay. Native memory or approval features must map to these controls, not bypass them.'),note('Do not expose every SDK feature by default','Terminal, browser, arbitrary plugins, external MCP and network actions require isolation, authentication and review. Full parity is not a safe production default.')]},
{id:'data',label:'Data & memory',title:'04 / Evidence, conversation and memory are different records',description:'Keep immutable source material, operational state, native continuation and derived knowledge separate—even before moving beyond SQLite.',height:865,groups:[g('Source → model context',16,20,1108,220),g('Current persistence domains',16,280,1108,235),g('Target data platform',16,555,1108,285)],nodes:[
n('d1','Raw source record','Original payload + source + observed time','current',32,95,'The events table is the benchmark source of truth. Cohorts are derived from event IDs; current severity labels are review priorities, not detector confidence.','Benchmark record from explicit import.','Stable evidence ID and raw JSON.',['Do not overwrite source records with model interpretations.','Pilot export contains events only.'],'Importer rejects existing destination; incomplete imports must not become published evidence.','services/import_corpus.py · export_pilot.py · store.py'),
n('d2','Case-scoped evidence view','Query → bounded excerpt → reference','current',411,95,'The same record can be viewed fully by the analyst but excerpted for the model. Findings cite evidence IDs, not untraceable summaries alone.','Case filter and evidence ID.','Scoped excerpt with retrievable original.',['SQL parameters and server-side case clause.','Model text may truncate; original stays available.'],'If a record is outside scope or absent, deny it; do not retrieve a substitute silently.','services/store.py · engine.py'),
n('d3','Working context','Summary + recent messages + tool receipts','partial',790,95,'An ephemeral model input assembled from durable records and native SDK state. Relay compaction retains the last checkpoint summary and resets native continuation.','Selected evidence, prompts, history and tool definitions.','Bounded input for the selected model.',['Default Relay threshold: 24,000 characters.','Raw audit remains intact after compaction.'],'Summary can omit details; cite original evidence before consequential findings.','services/engine.py · store.py'),
n('d4','Operational database','Sessions · trace · approval · questions','current',32,355,'SQLite WAL stores Relay state. Tables cover session config/parent, sequenced trace, pending approvals and receipts, analyst questions and runtime enable switches.','Run and human decision events.','Durable session timeline and control records.',['Foreign keys enabled.','No tenant model or production role separation today.'],'Receipt persistence and side effects are not one universal atomic transaction; recover conservatively.','services/store.py: initialize'),
n('d5','Derived case knowledge','Memory · tasks · artifact versions','current',411,355,'Findings and reports are separate from evidence. A report restore writes a new version rather than deleting history. Memory is case-scoped and approved.','Finding + evidence IDs; task/status; artifact content.','relay_memory, relay_tasks, relay_artifacts, relay_artifact_versions.',['Evidence membership checked for memory.','Tasks and artifacts scoped to session.'],'Stale or mistaken memory needs analyst correction; no autonomous learning approval bypass.','services/advanced.py · store.py'),
n('d6','Native continuation','JSON anchors + SDK-owned stores','partial',790,355,'Most adapters serialize native messages/state into relay_native_state. Pi uses JSONL; Deep Agents uses SQLite checkpoints; Claude uses SDK sessions; OpenCode state lives on its server.','Validated successful run state; Claude SDK session reference.','Per-session/runtime/epoch continuation.',['JSON state limit 4 MiB.','Branch isolates native calls; failed non-Claude runs retain prior anchor.'],'A main-database-only backup is insufficient for full native resume.','services/adapters/state.py · SDK_COVERAGE.md'),
n('d7','PostgreSQL + object store','Operational rows + immutable large blobs','target',32,655,'Proposed scale-out split: PostgreSQL for transactional state, object storage for raw batches/reports/native snapshots. Store checksums, tenant, provenance and retention metadata.','Versioned imports and operational events.','Queryable relational state and immutable blob references.',['Migration must verify counts, checksums and access scope.','Do not dual-write informally or share SQLite across replicas.'],'Restore rehearsal and cutover/rollback plan required before traffic migration.','Target schema and migration design'),
n('d8','Retrieval / Mem0 adapter','Optional derived index; not source of truth','target',411,655,'Optional semantic retrieval sits behind the Relay memory service. It must retain evidence lineage and enforce tenant/case filters independently of ranking.','Approved memory text and scoped evidence references.','Candidate references for authorized rehydration.',['No raw corpus-wide vector access for agents.','Deletion, retention and poisoning review required.'],'Index outage must not corrupt evidence or operational state; use scoped source lookup.','Target memory interface; no Mem0/vector integration today'),
n('d9','Ingest & lineage pipeline','Validate · normalize · deduplicate · quarantine','target',790,655,'Live telemetry needs authenticated source adapters, event-time handling, schema versions, source offsets and bounded retry. OpenTelemetry run export does not implement this.','Signed/authenticated sensor batches or source API cursors.','Canonical events, provenance and rejected-record queue.',['Proposed dedupe key: source identity + native record ID + payload hash.','Separate observed time and received time.'],'Backpressure and dead-letter handling must preserve replayability and surface missing data.','Target ingestion service')],edges:[e('d1','d2'),e('d2','d3'),e('d1','d4'),e('d2','d5'),e('d3','d6'),e('d4','d7','migrate',true),e('d5','d8','index',true),e('d9','d7','normalized events',true,'bottom-return'),e('d7','d8','scoped lookup',true),e('d9','d8','references',true)],notes:[note('Current logical relationships','events → derived case cohort; case → sessions; session → trace / approvals / questions / tasks / artifacts / native state; artifact → versions; memory → case + session + evidence IDs. Not every relationship is enforced as a SQL foreign key.'),note('Proposed portable event envelope','schema_version, event_id, tenant_id, case_id, run_id, session_id, parent_run_id, seq, occurred_at, kind, payload, provenance_ref, policy_version, trace_id. This is a target contract, not the current NDJSON wire schema.'),note('Do not confuse four meanings of “memory”','Model context is input; native session state is continuation; approved case memory is derived knowledge; the event archive is evidence. Their retention, trust and deletion rules differ.')]},
{id:'security',label:'Trust & safety',title:'05 / Authority belongs to policy and the analyst',description:'Untrusted evidence and model output may suggest actions. Neither can grant permissions. Current controls and production gaps are shown separately.',height:855,groups:[g('Current request and execution boundary',16,20,1108,225),g('Current policy and output boundary',16,280,1108,225),g('Production hardening gates',16,550,1108,280)],nodes:[
n('s1','Operator identity','Shared token → secure session cookie','partial',32,95,'The deployed pilot has single-operator token login, not a multi-user identity system. Sessions are in memory and expire after eight hours or process restart.','Operator login token through HTTPS.','Secure HttpOnly SameSite=Strict __Host-relay cookie.',['Constant-time secret comparison; global login throttle.','Token excluded from Git/image; local copy protected by Windows DPAPI.'],'Restart/idle stop requires login again; shared token cannot establish individual accountability.','services/access.py · FLY_PILOT.txt'),
n('s2','Request & admission checks','Host · Origin · JSON · worker limits','current',411,95,'The API checks expected origin/host and gates requests before sensitive operations. Run admission bounds local concurrent work.','Browser request and session cookie.','Authorized, bounded API operation.',['CSP, no-store, HSTS in pilot, nosniff.','Finite HTTP workers and agent-run semaphore.'],'Unauthenticated API, wrong-origin POSTs and capacity excess are rejected.','services/access.py · app.py'),
n('s3','Credential & worker scope','Selected keys · private SDK homes','partial',790,95,'Worker environments avoid inheriting unnecessary secrets and personal SDK profiles. This reduces accidental configuration leakage but is not an OS security perimeter.','Selected adapter configuration and provider key.','Private process environment and bounded SDK toolset.',['No arbitrary executable plugins or general shell/browser tools.','Non-root container user in Fly pilot.'],'A compromised in-process SDK still has process capabilities; isolate before adding hostile code tools.','workers/python-bridge · Dockerfile'),
n('s4','Case and tool authorization','Read-only / ask-all / supervised','current',32,355,'Tool execution checks selected case, permitted feature and effect type. Source log text and memory are data even when they contain apparent instructions.','Model tool request and session policy.','Denied call or bounded approved action.',['No prompt-only permission enforcement.','Write and simulation tools require approval.'],'Do not treat an injected instruction in logs as analyst consent.','services/engine.py · advanced.py'),
n('s5','Exact-argument approval','One pending decision; explicit receipt','current',411,355,'The analyst reviews the stored operation. Reusing a resolved approval fails. Approval does not authorize different arguments or new actions.','Tool call, argument snapshot, human decision.','Execution receipt, denial or expiry.',['Bounded waits; cancel pending work on interruption.','Native workspace operations are separately validated.'],'No exactly-once claim across process crash or external effect; investigate uncertain outcomes.','services/engine.py · workspace.py'),
n('s6','Output and action boundary','Citations · versioned reports · dry-run','partial',790,355,'Model findings must remain distinguishable from observed facts. Current containment is simulation only; no security control system is contacted.','Proposed findings, evidence IDs and action target.','Auditable report or simulated decision.',['Typed findings when integrated.','Keep uncertainty and incomplete coverage visible.'],'Do not convert a benchmark event into a confirmed incident or fake remediation receipt.','services/adapters/common.py · engine.py'),
n('s7','Tenant & role separation','OIDC · MFA · RBAC · database policies','target',32,650,'Proposed production roles: viewer, investigator, approver and administrator. Resolve tenant membership on the server and enforce every storage/tool boundary.','Verified identity claims and tenant membership.','Tenant-bound session and least-privilege authorization.',['Supabase is an optional Postgres/auth candidate, not configured.','High-impact writes need independent approval where appropriate.'],'Cross-tenant negative tests and privilege-revocation tests are release gates.','Production identity design'),
n('s8','Isolated execution & egress','Per-run sandbox · capability-scoped access','target',411,650,'Place risky tools in short-lived workers with no host filesystem, container daemon or broad network credentials. The shared gateway remains the authority.','Signed short-lived job capability and tool allowlist.','Audited effects through narrow connectors.',['Allowlisted destinations; quotas; secrets broker.','Default no arbitrary MCP/plugin loading.'],'Deny egress and filesystem access outside explicit grants; kill worker on limit.','Production worker isolation design'),
n('s9','Response connector gate','Plan → approve → apply → verify','target',790,650,'Real remediation requires connector-specific target validation, permission, idempotency and post-action verification. Keep simulation separate even after connectors arrive.','Human-approved exact action with expiry and policy version.','External operation ID and independently verified state.',['Least-privilege service identity; blast-radius limits.','Compensation strategy where possible.'],'Unknown external outcome goes to reconciliation, not automatic repeat execution.','Target response control plane')],edges:[e('s1','s2'),e('s2','s3'),e('s1','s4'),e('s4','s5'),e('s5','s6'),e('s4','s7','identity gate',true),e('s5','s8','execution gate',true),e('s6','s9','action gate',true),e('s7','s8','scoped capability',true),e('s8','s9','connector',true)],notes:[note('Threat model','Primary risks: prompt injection through logs/memory, cross-case or cross-tenant evidence leakage, tool abuse, SDK/plugin supply-chain compromise, secret exfiltration and duplicate side effects after retry.'),note('Current protections are bounded','The pilot has access controls, case-scoped tools and a small approved toolset. It is not a hostile-code sandbox, a multi-user SOC, or a certified security product.'),note('Required red-team acceptance','Exercise malicious log instructions, forged approval IDs, changed tool arguments, cross-case evidence IDs, disabled features, stale tokens and repeated callbacks. Production adds tenant escapes and worker-egress tests.')]},
{id:'deploy',label:'Deployment',title:'06 / Keep the pilot small; split state before scaling',description:'The upper two rows describe the recorded Fly pilot. The bottom row is a proposed migration—not infrastructure already provisioned.',height:865,groups:[g('Deployed edge and application · Fly / Toronto',16,20,1108,230),g('Current persistent and operational boundary',16,285,1108,225),g('Target scale-out topology · approval required before provisioning',16,555,1108,285)],nodes:[
n('f1','HTTPS edge → operator login','socharness-mandil.fly.dev','current',32,95,'Fly serves the protected pilot over HTTPS. Login and browser API share one origin. Deployment record includes anonymous denial, origin rejection and logout checks.','Public HTTPS traffic.','Authenticated requests forwarded to the application.',['Shared operator token only.','No model keys in the deployed environment.'],'An available landing page is not proof of model readiness or security sensor ingestion.','FLY_PILOT.txt'),
n('f2','One Fly machine','shared CPU · 2 GB RAM · yyz','current',411,95,'One non-root Python/Node container serves UI, API and agent workers. Idle auto-stop and HTTP auto-start are enabled; minimum running machines is zero.','HTTP requests and admitted agent runs.','Static UI, API, streaming and local subprocesses.',['Exactly one machine; max parallel runs one.','Node 24 and Python 3.12 cloud runtime.'],'Cold-start latency and session invalidation are expected. Do not scale this SQLite topology to replicas.','fly.toml · Dockerfile · FLY_PILOT.txt'),
n('f3','Local worker processes','No distributed queue today','partial',790,95,'Workers execute within the machine boundary. In-process run locks are not distributed leases. Hermes is absent from the cloud image; OpenCode is disabled.','Admitted runtime invocation.','SDK events and persisted run results.',['Parent deadline and cancellation.','Provider credentials must be provisioned deliberately.'],'Machine death interrupts work; no automatic durable execution resume.','services/app.py · workers/*'),
n('f4','Encrypted persistent volume','1 GB · SQLite + adapter files','current',32,355,'The pilot volume stores the benchmark database and runtime state. Data was verified across source-only redeploy and stop/start according to the deployment record.','Database writes and native SDK files.','Persistent evidence and session state.',['UID 10001; database mode 0600.','Benchmark export excluded local conversations.'],'Disk pressure can block both evidence and audit writes; define alerts before broader use.','FLY_PILOT.txt · services/store.py'),
n('f5','Backup & recovery boundary','5-day snapshots; restore drill pending','partial',411,355,'Daily Fly volume snapshots are enabled with five-day retention. They are not a complete off-machine, tested backup strategy.','Persistent data snapshots.','Limited recovery point history.',['Target: encrypted database + native-file export.','Backup OpenCode server state separately if enabled.'],'No demonstrated full restore/RPO/RTO claim; rehearse before production.','FLY_PILOT.txt · DEPLOYMENT.txt'),
n('f6','Release & observability','Pinned deps · contract tests · audit export','partial',790,355,'Recorded checks include 77 backend tests on Windows/Linux and separate SDK contract suites. Live HTTP acceptance passed; paid-provider quality was not tested.','Source image, test evidence, run trace.','Deployable image and acceptance record.',['No secrets or conversation history in source image.','No remote tracing service provisioned.'],'Target: artifact signing, dependency review, canary and rollback gates.','FLY_PILOT.txt · SDK_COVERAGE.md'),
n('f7','Stateless API + identity','Multiple replicas only after state split','target',32,655,'Move user identity to an OIDC-capable service and shared session/authorization state. Keep UI/API horizontally scalable only after operational state leaves local SQLite.','Verified user/tenant request.','Transactional job creation and streamed status.',['Possible managed Postgres/auth provider: Supabase; undecided.','No automatic production purchases.'],'Sticky sessions alone do not solve SQLite or cross-replica authorization.','Target control-plane service'),
n('f8','Durable jobs + isolated workers','Lease · heartbeat · retry · reconcile','target',411,655,'Proposed PostgreSQL-backed job queue first; add a dedicated broker only when measured load needs it. Workers use bounded leases and per-run capabilities.','Committed job record and policy snapshot.','Sequenced results, lease heartbeat, terminal status.',['Transactional outbox for publish consistency.','Idempotency key per external operation; no exactly-once promise.'],'Expired leases trigger reconciliation; do not repeat uncertain writes blindly.','Target worker and queue service'),
n('f9','Managed state + telemetry','Postgres · object store · OTLP collector','target',790,655,'Move relational state, large immutable evidence and run observability into separate services with access control, retention and restore drills.','Operational rows, evidence blobs, approved metrics/traces.','Durable shared state and operational dashboards.',['Encryption and tenant-scoped access.','Redact exports; budget retention and storage cost.'],'Define and test RPO/RTO, queue lag and error alerts before accepting a production SLO.','Target storage/observability services')],edges:[e('f1','f2'),e('f2','f3'),e('f2','f4'),e('f4','f5','snapshot'),e('f3','f6','events'),e('f4','f7','state migration',true),e('f5','f8','recovery gate',true),e('f6','f9','telemetry',true),e('f7','f8','enqueue',true),e('f8','f9','state / trace',true)],notes:[note('Do not add replicas to the current pilot','Separate operational state and durable job ownership first. SQLite WAL, local SDK homes and in-memory login/run state are not a shared distributed control plane.'),note('No database vendor is committed','PostgreSQL is the proposed operational model. Fly managed services or Supabase are candidates, not installed dependencies. Keep identity/storage choices behind explicit application interfaces.'),note('A safe migration sequence','Back up and restore-test → create versioned schema → import and verify checksums → rehearse jobs/approval recovery → cut over with a rollback point → load-test → only then enable additional workers.')]}
];
