const tools=[['query_case_evidence','Read','Bounded in-case evidence query; 1–25 records.'],['get_event','Read','Retrieve one in-case record with bounded model excerpt.'],['save_case_note','Approval','Persist an analyst-approved case note.'],['simulate_containment','Approval · dry-run','Record a decision only; no endpoint action.'],['search_memory','Read · memory','Search approved knowledge in this case.'],['remember_finding','Approval · memory','Store a finding with valid in-case evidence IDs.'],['list_tasks','Read','Read the session investigation plan.'],['set_task','Approval','Create or update an investigation task.'],['get_playbook','Read · skills','Read a curated playbook; not arbitrary skill discovery.'],['read_artifact','Read · artifacts','Read a session report and its versions.'],['write_artifact','Approval · artifacts','Create a new report version.'],['restore_artifact','Approval · artifacts','Restore old content as a new version.'],['ask_human','Read / input','Wait for a durable analyst answer; bounded active wait.'],['rewind_workspace','Approval · Claude only','Analyst-only native file rewind while the run is idle.']];
const roadmap=[['00 / BASELINE','Protected pilot','current','Keep the current scope explicit.',['11 restricted SDK adapters + replay.','Benchmark evidence; no live sensor stream.','One machine, one volume, single operator.','HTTP/auth and SDK contract evidence.'],'Gate: distinguish integrated, configured and live-verified.'],['01 / LEARN & VERIFY','Close adapter contracts','target','Add Strands and Mastra as bounded, independently tested integrations.',['Loop, tool schema and final-result tests.','Denied writes, cancellation and budget sharing.','Continuation, compaction and branch isolation.','Small approved live-provider acceptance.'],'Gate: no silent unsupported features or fake successful runs.'],['02 / HARDEN','Production foundations','target','Establish accountable identity, recoverability and execution isolation.',['Tenant/RBAC boundary and negative tests.','Postgres migration and full restore drill.','Durable job leases, outbox and reconciliation.','Per-run sandbox and egress restrictions.'],'Gate: measured recovery plus no duplicate unauthorized effects.'],['03 / OPERATE','Real SOC integrations','target','Connect approved telemetry before real response actions.',['Authenticated ingest, lineage and schema versions.','Quality evals against labeled investigation tasks.','Connector-specific approval and idempotency.','Load, cost and failure-recovery acceptance.'],'Gate: verified outcomes, not just a green dashboard.']];
const decisions=[['Keep SDKs native','Use adapters to normalize governance and traces; do not rebuild every SDK loop inside Relay. This preserves the learning goal and makes differences measurable.'],['Keep the UI decoupled','The existing plain-JavaScript UI is sufficient for the pilot. A future React/TypeScript migration is optional and should preserve API contracts rather than block agent work.'],['Make human authority explicit','Native approval APIs can implement a pause, but Relay’s stored exact-argument decision remains the authorization record. Long-running workflow suspension needs durable workers.'],['Separate facts from conclusions','Raw logs, agent findings, approved memory and response effects have different trust levels. Every derived conclusion must retain evidence references and uncertainty.'],['Do not scale prematurely','Move shared state and job ownership out of the single machine before adding replicas. A new database alone does not provide crash-safe tool execution.'],['Measure coverage honestly','Report per-feature integration and test evidence. No synthetic “100% all SDKs” score; unknown, shared, native, policy-disabled and unverified states are meaningful.']];
const verification=[note('Recorded acceptance','77 backend tests passed on Windows and Linux. Separate Node, extended Python and Hermes SDK contract suites use fake model transports. Fly HTTP/auth and persistence checks are documented in FLY_PILOT.txt.','current'),note('Quality evaluation plan','Build labeled SOC investigation tasks with required evidence references. Measure factual support, missed relevant evidence, false assertions, denied-action behavior, analyst correction rate, latency and measured cost. No quality scores are claimed here.','target'),note('Operational objectives to agree','Set RPO/RTO after a restore drill; p95 queue/turn latency after load testing; cost ceilings after provider acceptance. Alert on disk pressure, error rate, queue age, approval expiry and worker lease loss. Values are deliberately not invented.','target')];
let activeView=0,selected=0,zoom=1,running=!matchMedia('(prefers-reduced-motion: reduce)').matches;
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=s=>`<span class="tag ${s}">${statusText[s]}</span>`;
const sections=[...views.map(v=>[v.id,v.label]),['catalog','SDKs & tools'],['roadmap','Delivery gates']];
$('tabs').innerHTML=sections.map(([id,label],i)=>`<button type="button" role="tab" id="tab-${id}" aria-controls="${i<views.length?'diagram':id}-panel" aria-selected="${i===0}" data-index="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('');
function cardHTML(c){return `<article class="card">${c.status?badge(c.status):''}<h3>${esc(c.title)}</h3><p>${esc(c.text)}</p></article>`;}
function selectNode(index){const v=views[activeView];selected=(index+v.nodes.length)%v.nodes.length;const a=v.nodes[selected];document.querySelectorAll('.node').forEach((b,i)=>{b.classList.toggle('selected',i===selected);b.setAttribute('aria-pressed',String(i===selected));});$('inspector').innerHTML=`<div>${badge(a.status)}<h3>${esc(a.title)}</h3><p class="desc">${esc(a.description)}</p></div><div class="detail-section"><h4>Inputs</h4><p>${esc(a.inputs)}</p></div><div class="detail-section"><h4>Outputs / contract</h4><p>${esc(a.outputs)}</p></div><div class="detail-section"><h4>Controls & invariants</h4><ul>${a.controls.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail-section"><h4>Failure / boundary</h4><p>${esc(a.failure)}</p></div><div class="source"><small>Implementation or design source</small><code>${esc(a.source)}</code></div>`;document.querySelectorAll('.wire').forEach(w=>w.classList.toggle('active',w.dataset.from===a.id||w.dataset.to===a.id));}
function pathFor(a,b,route){const ac=[a.x+159,a.y+100],bc=[b.x+159,b.y];if(route==='final-route')return `M${a.x+318} ${a.y+50} H1134 V550 H8 V${b.y+50} H${b.x}`;if(route==='read-route')return `M${a.x+159} ${a.y+100} V540 H${b.x+159} V${b.y+100}`;if(route==='bottom-return')return `M${a.x+159} ${a.y+100} V810 H${b.x+159} V${b.y+100}`;if(route==='outer-right')return `M${a.x+318} ${a.y+50} H1133 V${b.y+50} H${b.x+318}`;if(route==='up-right')return `M${a.x+318} ${a.y+50} H762 V${b.y+50} H${b.x}`;if(route==='loop-top')return `M${a.x+159} ${a.y} V263 H${b.x+159} V${b.y+100}`;if(a.y===b.y){const right=b.x>a.x;return `M${a.x+(right?318:0)} ${a.y+50} H${b.x+(right?0:318)}`;}if(a.x===b.x)return `M${ac[0]} ${ac[1]} V${bc[1]}`;const right=b.x>a.x;const ax=a.x+(right?318:0),bx=b.x+(right?0:318),mid=(ax+bx)/2;return `M${ax} ${a.y+50} H${mid} V${b.y+50} H${bx}`;}
function draw(){const v=views[activeView];$('stage').dataset.view=v.id;$('view-title').textContent=v.title;$('view-description').textContent=v.description;$('stage').style.height=v.height+'px';let html=v.groups.map((a,i)=>`<div class="group" data-group="${i}"><strong>${esc(a.title)}</strong></div>`).join('');let wire=`<svg class="wires" height="${v.height}" viewBox="0 0 1140 ${v.height}" aria-hidden="true"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="var(--muted)"/></marker></defs>`;v.edges.forEach((edge,i)=>{const a=v.nodes.find(n=>n.id===edge.from),b=v.nodes.find(n=>n.id===edge.to);wire+=`<path id="edge-${i}" class="wire ${edge.planned?'planned':''}" data-from="${a.id}" data-to="${b.id}" d="${pathFor(a,b,edge.route)}" marker-end="url(#arrow)"/><circle r="3" class="packet ${edge.planned?'planned':''}"><animateMotion dur="${3.1+(i%4)*.7}s" repeatCount="indefinite" begin="${-(i%5)}s"><mpath href="#edge-${i}"/></animateMotion></circle>`;if(edge.label){let x=(a.x+b.x)/2+159,y=(a.y+b.y)/2+47;if(a.x===b.x){x=a.x+168;y=(a.y+b.y+100)/2;}if(edge.route==='final-route'){x=920;y=567;}if(edge.route==='read-route'){x=350;y=535;}if(edge.route==='bottom-return'){x=570;y=805;}if(edge.route==='outer-right'){x=1073;y=595;}if(edge.route==='loop-top'){x=560;y=260;}if(edge.route==='up-right'){x=756;y=410;}wire+=`<text class="wire-label" text-anchor="middle" x="${x}" y="${y}">${esc(edge.label)}</text>`;}});wire+='</svg>';html+=wire;html+=v.nodes.map((a,i)=>`<button class="node ${a.status}" data-node="${i}" data-component="${a.id}" aria-label="${esc(a.title)} — ${statusText[a.status]}" aria-pressed="false"><span class="meta"><span class="idx">${esc(a.id.toUpperCase())}</span>${badge(a.status)}</span><strong>${esc(a.title)}</strong><span class="sub">${esc(a.sub)}</span></button>`).join('');$('stage').innerHTML=html;$('view-notes').innerHTML=v.notes.map(cardHTML).join('');$('stage').querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>selectNode(Number(b.dataset.node)));selectNode(0);fit();setMotion();}
function resize(){const v=views[activeView];if(!v)return;$('stage').style.transform=`scale(${zoom})`;$('stage-wrap').style.width=(1140*zoom)+'px';$('stage-wrap').style.height=(v.height*zoom)+'px';$('fit').textContent=Math.round(zoom*100)+'% · Fit';}
function fit(){zoom=Math.max(.85,Math.min(1.15,$('viewport').clientWidth/1140));resize();}
function setMotion(){$('stage').classList.toggle('paused',!running);const svg=$('stage').querySelector('svg');if(svg){running?svg.unpauseAnimations():svg.pauseAnimations();}$('pause').textContent=running?'Pause flow':'Play flow';}
function openTab(index){document.querySelectorAll('[role=tab]').forEach((b,i)=>b.setAttribute('aria-selected',String(i===index)));$('diagram-panel').hidden=index>=views.length;$('catalog-panel').hidden=index!==views.length;$('roadmap-panel').hidden=index!==views.length+1;if(index<views.length){activeView=index;$('diagram-panel').setAttribute('aria-labelledby','tab-'+views[index].id);draw();}else $(index===views.length?'catalog-panel':'roadmap-panel').setAttribute('aria-labelledby','tab-'+sections[index][0]);}
$('tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>openTab(Number(b.dataset.index)));
$('tabs').onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const buttons=[...$('tabs').querySelectorAll('button')];const i=buttons.indexOf(document.activeElement);if(i<0)return;event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(i+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();openTab(next);};
$('theme').onclick=()=>{const light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':'dark';$('theme').textContent=light?'Dark theme':'Light theme';};
$('pause').onclick=()=>{running=!running;setMotion();};$('current-only').onchange=()=>{$('stage').classList.toggle('current-only',$('current-only').checked);};$('plus').onclick=()=>{zoom=Math.min(1.5,zoom+.1);resize();};$('minus').onclick=()=>{zoom=Math.max(.85,zoom-.1);resize();};$('fit').onclick=fit;$('next').onclick=()=>selectNode(selected+1);$('previous').onclick=()=>selectNode(selected-1);
function renderSDKs(){const query=$('sdk-search').value.toLowerCase().trim();const rows=sdks.filter(s=>s.join(' ').toLowerCase().includes(query));$('sdk-count').textContent=`${rows.length} of 13 SDK entries · 11 implemented adapters · 2 proposed · replay is separate`;$('sdk-body').innerHTML=rows.length?rows.map(s=>`<tr><td>${esc(s[0])}<p>${esc(s[1])}</p>${badge(s[2])}</td><td>${esc(s[3])}</td><td>${esc(s[4])}</td><td>${esc(s[5])}</td></tr>`).join(''):'<tr><td colspan="4">No SDK matches. Try a framework name or capability.</td></tr>';}
$('sdk-search').oninput=renderSDKs;$('tools').innerHTML=tools.map(t=>`<article class="tool"><code>${esc(t[0])}</code><p>${esc(t[2])}</p><span class="tag">${esc(t[1])}</span></article>`).join('');
$('roadmap').innerHTML=roadmap.map(r=>`<article class="card"><span class="number">${r[0]}</span>${badge(r[2])}<h3>${r[1]}</h3><p>${r[3]}</p><ul>${r[4].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="callout">${r[5]}</div></article>`).join('');$('decisions').innerHTML=decisions.map(d=>`<div class="decision"><h3>${d[0]}</h3><p>${d[1]}</p></div>`).join('');$('verification').innerHTML=verification.map(cardHTML).join('');
// The print appendix is intentionally complete even when the interactive view shows one section.
$('print-appendix').innerHTML='<h2>Complete architecture specification</h2>'+views.map(v=>`<section><h2>${esc(v.title)}</h2><p>${esc(v.description)}</p>${v.nodes.map(a=>`<article><h3>${esc(a.id.toUpperCase()+' · '+a.title)} — ${statusText[a.status]}</h3><p>${esc(a.description)}</p><p><b>Input:</b> ${esc(a.inputs)} <b>Output:</b> ${esc(a.outputs)}</p><p><b>Controls:</b> ${esc(a.controls.join(' '))}</p><p><b>Failure boundary:</b> ${esc(a.failure)}</p><p><b>Source:</b> ${esc(a.source)}</p></article>`).join('')}<p><b>Flows:</b> ${v.edges.map(a=>esc(a.from+' → '+a.to+(a.planned?' [target]':''))).join('; ')}</p></section>`).join('')+'<h2>SDK integration boundary</h2>'+sdks.map(s=>`<article><h3>${esc(s[0])} — ${statusText[s[2]]}</h3><p>${esc(s[1]+' · '+s[3])}</p><p>${esc(s[4]+' '+s[5])}</p></article>`).join('')+'<h2>Governed tools</h2>'+tools.map(t=>`<p><b>${esc(t[0])}</b> · ${esc(t[1]+' — '+t[2])}</p>`).join('')+'<h2>Delivery gates</h2>'+roadmap.map(r=>`<article><h3>${esc(r[0]+' · '+r[1])}</h3><p>${esc(r[3]+' '+r[4].join(' ')+' '+r[5])}</p></article>`).join('');
$('print').onclick=()=>window.print();renderSDKs();openTab(0);new ResizeObserver(()=>{if(!$('diagram-panel').hidden)fit();}).observe($('viewport'));
